mapper.select:
SELECT b.id, b.title, b.content, b.cover, b.views, b.likes, b.dislikes, b.collections, b.publish_time, b.create_time, u.id AS userId, u.username, u.avatar, c.name AS categoryName, col.collect_time AS collectTime FROM collection col JOIN blog b ON col.blog_id = b.id JOIN user u ON b.user_id = u.id LEFT JOIN category c ON b.category_id = c.id WHERE col.user_id = #{userId}
AND (b.title LIKE CONCAT('%', #{title}, '%') OR b.content LIKE CONCAT('%', #{title}, '%'))
AND b.category_id = #{categoryId}
ORDER BY col.collect_time DESC
